import sys
sys.path.append('storage/ariadne')

import jax
import jax.numpy as jnp
import optax

from models_fact_ln import Osc2CtxAdaptiveFactorizedL_LN
from losses import mae_with_temporal_curvature

BASE_SEED = 42
BATCH_SIZE = 8
V_ORTHO_LAM = 1e-5
U_ORTHO_LAM = 1e-6
GAMMA_PRIOR_LAM = 5e-6

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'rank_k': 320,
        'proj_rank': 34,   # fine-grained p
        'hidden_size': 96,
        'normalize_u': True,
        'gamma_start': 0.25,
        'gamma_end': 0.99,
        'a_max': 0.993
    }

class Wrapper:
    def __init__(self, **kwargs):
        self.model = Osc2CtxAdaptiveFactorizedL_LN(**kwargs)
        self.needs_rng = False
    def init(self, rng_key, dummy_input):
        return self.model.init(rng_key, dummy_input, training=True)
    def apply(self, params, x, training=False, mutable=None, rngs=None):
        return self.model.apply(params, x, training=training)

def create_network(hparams):
    return Wrapper(
        rank_k=int(hparams.get('rank_k', 320)),
        proj_rank=int(hparams.get('proj_rank', 34)),
        hidden_size=int(hparams.get('hidden_size', 96)),
        normalize_u=bool(hparams.get('normalize_u', True)),
        gamma_start=float(hparams.get('gamma_start', 0.25)),
        gamma_end=float(hparams.get('gamma_end', 0.99)),
        a_max=float(hparams.get('a_max', 0.993))
    )

def _get_from_tree(tree, key):
    # robust fetch for FrozenDict/dicts
    try:
        if key in tree:
            return tree[key]
    except Exception:
        pass
    if isinstance(tree, dict) and 'params' in tree:
        return _get_from_tree(tree['params'], key)
    try:
        return _get_from_tree(dict(tree), key)
    except Exception:
        raise KeyError(f"{key} not found")

def _col_norm(x, axis):
    return jnp.linalg.norm(x, axis=axis, keepdims=True) + 1e-6

def compute_loss(predictions, targets, params, x):
    base = mae_with_temporal_curvature(predictions, targets, params, x, lam=1e-4)
    # V orthonormal penalty on column-normalized V
    try:
        V = _get_from_tree(params, 'V')  # (k,p)
        Vn = V / _col_norm(V, axis=0)
        GV = Vn.T @ Vn
        IV = jnp.eye(GV.shape[0], dtype=GV.dtype)
        v_ortho = jnp.sum((GV - IV) ** 2)
    except Exception:
        v_ortho = 0.0
    # U orthonormal penalty on column-normalized U
    try:
        U = _get_from_tree(params, 'U')  # (N,p)
        Un = U / _col_norm(U, axis=0)
        GU = Un.T @ Un
        IU = jnp.eye(GU.shape[0], dtype=GU.dtype)
        u_ortho = jnp.sum((GU - IU) ** 2)
    except Exception:
        u_ortho = 0.0
    # Tiny γ prior toward linear schedule in prob space
    try:
        gamma_raw = _get_from_tree(params, 'gamma_raw')  # (T,)
        gamma = jax.nn.sigmoid(gamma_raw)
        T = gamma.shape[0]
        t = jnp.linspace(0.0, 1.0, T, dtype=gamma.dtype)
        sched = 0.25 + (0.99 - 0.25) * t
        g_prior = jnp.sum((gamma - sched) ** 2)
    except Exception:
        g_prior = 0.0
    return base + V_ORTHO_LAM * v_ortho + U_ORTHO_LAM * u_ortho + GAMMA_PRIOR_LAM * g_prior

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adam(learning_rate=learning_rate, eps=1e-8)
    )
